def write_csv(path, header, rows):
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=header, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)


def main():
    with (BASE / "surfaces.csv").open(encoding="utf-8-sig", newline="") as handle:
        candidates = [row for row in csv.DictReader(handle) if row["evidence_level"] == "source-candidate"]
    sources = sorted({row["source_file"] for row in candidates})
    assert {Path(path).name for path in sources} == REVIEWS.keys()
    files, surfaces, resolutions = [], [], []
    for source in sources:
        name = Path(source).name
        symbol, entry, state, disposition, evidence = REVIEWS[name]
        identifier = "semantic-launcher." + name.replace(".", "-").replace("_", "-")
        data = (ROOT / source).read_bytes()
        files.append({"source_file": source, "disposition": "full-source-read-and-bounded-consumer-trace", "evidence": evidence + f" Source sha256={hashlib.sha256(data).hexdigest()}; scope is this file and named consumers, not native execution."})
        surfaces.append(dict(zip(HEADER, [identifier, "Launcher/installer diagnostic semantics", source, symbol, entry, state, disposition, evidence, "reviewed-source-family-no-runtime", "", "No native installer/GUI/process/storage/update operation executed. One row groups related branch states; not a unique screen/defect count or full transitive diagnostic audit."])))
        for candidate in candidates:
            if candidate["source_file"] != source:
                continue
            line = int(re.match(r"L(\d+):", candidate["source_finding"])[1])
            resolved = disposition
            detail = evidence
            if name == "main.rs" and line in {414, 451}:
                resolved = "pre-window-startup-or-panic-not-current-UI-alert"
            elif name == "prepare-component.ps1" and line in {31, 54}:
                resolved = "retained-report-detail-or-replaced-before-installer-summary"
            elif name == "activate-update.mjs" and line in {73, 76}:
                resolved = "rollback-export-no-reviewed-production-UI-caller"
            elif name == "verify-runtime.mjs" and line == 15:
                resolved = "invariant-guard-not-normal-executed-UI-state"
            resolutions.append({"candidate_id": candidate["surface_id"], "source_file": source, "line": line, "family_id": identifier, "disposition": resolved, "consumer_evidence": detail, "evidence_level": "source-reviewed-not-runtime"})
    write_csv(OUT / "files.csv", ["source_file", "disposition", "evidence"], files)
    write_csv(OUT / "surfaces.csv", HEADER, surfaces)
    write_csv(OUT / "candidate-resolutions.csv", ["candidate_id", "source_file", "line", "family_id", "disposition", "consumer_evidence", "evidence_level"], resolutions)
    report = {"schema_version": 1, "primary_files": len(files), "reviewed_families": len(surfaces), "candidate_resolutions": len(resolutions), "unresolved_candidate_ids": sorted({row['surface_id'] for row in candidates} - {row['candidate_id'] for row in resolutions}), "runtime_signoff": False, "native_execution": False}
    (OUT / "validation.json").write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()
